import java.util.*;

class Solution {
  public int maxPossibleScore(int[] start, int d) {
    Arrays.sort(start);
    long lo = 0, hi = (long) start[start.length - 1] + d - start[0];
    while (lo < hi) {
      long mid = lo + (hi - lo + 1) / 2;
      long previous = start[0];
      boolean ok = true;
      for (int i = 1; i < start.length; i++) {
        previous = Math.max((long) start[i], previous + mid);
        if (previous > (long) start[i] + d) {
          ok = false;
          break;
        }
      }
      if (ok) lo = mid;
      else hi = mid - 1;
    }
    return (int) lo;
  }
}
